<?php session_start();require_once __DIR__.'/../../conn.php';require_once __DIR__.'/../../auth.php';require_once __DIR__.'/../../sort_utils.php';requireStaff();$allowed=['customer_id'=>'ID','customer_name'=>'Name','contact_number'=>'Contact','address'=>'Address'];list($sort,$order)=get_sort_params($allowed,'customer_id');$r=mysqli_query($conn,"SELECT * FROM Customer ".sort_clause($sort,$order));$rs=array();while($rw=mysqli_fetch_assoc($r))$rs[]=$rw;mysqli_free_result($r);mysqli_close($conn);?><!DOCTYPE html><html><head><meta charset="UTF-8"><title>View Customers</title><link rel="stylesheet" href="../style.css"><style>.mc{flex:1;display:flex;flex-direction:column;overflow-y:auto;padding:24px 32px}.tw{background:#fff;border-radius:20px;padding:20px;overflow-x:auto;box-shadow:0 1px 3px rgba(0,0,0,.06)}table{width:100%;border-collapse:collapse;table-layout:fixed}th,td{padding:12px 14px;border-bottom:1px solid #e0e0e0;text-align:center}th{font-weight:500;color:#5f6368;font-size:13px}</style></head><body><div id="sidebar-container"></div><div class="mc"><div class="top-bar"><div class="page-title">View Customers</div></div><div class="content-container"><div class="tw"><table><thead><tr><th><?php echo sortable_th('customer_id','ID',$sort,$order);?></th><th><?php echo sortable_th('customer_name','Name',$sort,$order);?></th><th><?php echo sortable_th('contact_number','Contact',$sort,$order);?></th><th><?php echo sortable_th('address','Address',$sort,$order);?></th></tr></thead><tbody><?php foreach($rs as $rw):?><tr><td>#<?php echo $rw['customer_id'];?></td><td><strong><?php echo htmlspecialchars($rw['customer_name']);?></strong></td><td><?php echo htmlspecialchars(isset($rw['contact_number'])?$rw['contact_number']:'-');?></td><td><?php echo htmlspecialchars(isset($rw['address'])?$rw['address']:'-');?></td></tr><?php endforeach;?></tbody></table></div></div></div><script src="../sidebar.js"></script><script>loadSidebar('view-customers');</script></body></html>
